toad_implementation.code_blueprint:
canvas {
  size: 800px 800px;
  fill: #020208;
  font-family: "Space Mono, monospace";
}

>voidBlack = #020208;
>hAlpha = #D91B5C;
>oIII = #00C8FF;
>starLight = #FFE680;
>crosshair = #2D3748;

circle #outerGasNebula {
  at: center of canvas offset 0px -40px;
  size: 420px;
  fill: alpha(>hAlpha, 0.28);
}

circle #innerOxygenCore {
  at: center of #outerGasNebula;
  size: 260px;
  fill: alpha(>oIII, 0.35);
}

circle #stellarCore {
  at: center of #innerOxygenCore;
  size: 32px;
  fill: >starLight;
}

circle #reticleRing {
  at: center of #outerGasNebula;
  size: 480px;
  fill: none;
  stroke: >crosshair;
  stroke-width: 1px;
}

text #targetCatalogue {
  at: below #reticleRing offset 56px;
  content: "MESSIER 42 // THE ORION NEBULA";
  font-size: 20px;
  font-weight: 700;
  color: #FFFFFF;
}

text #astronomyData {
  at: below #targetCatalogue offset 10px;
  content: "RA 05h 35m 17s  •  DEC -05° 23' 28\"  •  DIST: 1,344 LY";
  font-size: 11px;
  color: >oIII;
}
